from ta_moler.cmd.airscale.genericairscale import GenericAirscale
from moler.exceptions import ParsingDone
from moler.helpers import convert_to_number
import re


class DbgrrcGet(GenericAirscale):
    """Command dbgrrc get."""

    def __init__(self, connection, options=None, port=None, prompt=None, newline_chars=None, runner=None):
        """
        Command dbgrrc get.

        :param port: port number
        :param connection: moler connection to device, terminal when command is executed
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(DbgrrcGet, self).__init__(connection=connection, prompt=prompt, newline_chars=newline_chars,
                                        runner=runner)
        self.port = port
        self.options = options

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = f"dbgrrc get port {self.port} {self.options}"
        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_port_speed(line)
                self._parse_port_speed_failure(line)
                self._parse_mtu(line)
            except ParsingDone:
                pass
        return super(DbgrrcGet, self).on_new_line(line, is_full_line)

    # Port 2 speed: 10000
    _re_port_speed = re.compile(r"Port\s\d+\sspeed:\s(?P<SPEED>\d+)")

    def _parse_port_speed(self, line):
        if self._regex_helper.search_compiled(DbgrrcGet._re_port_speed, line):
            self.current_ret["SPEED"] = convert_to_number(self._regex_helper.group('SPEED'))
            raise ParsingDone

    # Get port 4 speed failure: 3
    _re_port_speed_failure = re.compile(r"Get\sport\s\d+\sspeed\sfailure:\s(?P<SPEED_FAILURE>\d+)")

    def _parse_port_speed_failure(self, line):
        if self._regex_helper.search_compiled(DbgrrcGet._re_port_speed_failure, line):
            self.current_ret["SPEED_FAILURE"] = convert_to_number(self._regex_helper.group('SPEED_FAILURE'))
            raise ParsingDone

    # MTU for port 2 is 8192
    _re_port_mtu = re.compile(r"MTU\sfor\sport\s\d+\sis\s(?P<MTU>\d+)")

    def _parse_mtu(self, line):
        if self._regex_helper.search_compiled(DbgrrcGet._re_port_mtu, line):
            self.current_ret["MTU"] = convert_to_number(self._regex_helper.group('MTU'))
            raise ParsingDone


COMMAND_OUTPUT_SPEED = """root@0xe019:~ > dbgrrc get port 2 speed
Port 2 speed: 10000
root@0xe019:~ > """

COMMAND_KWARGS_SPEED = {
    "port": 2,
    "options": "speed"
}

COMMAND_RESULT_SPEED = {
    "SPEED": 10000
}

